using Kerf.Engine.Foundation;

using Kerf.Engine.Geometry;

using Kerf.Engine.Geometry.Objects;
using Kerf.Geometry;
using Occt;

namespace Kerf.Geometry;

/// <summary>
/// A torus, generated by rotating a circle of radius MinorRadius about the main axis of the local coordinate
/// system, its centre at distance MajorRadius from that axis.
/// P(U, V) = O + (R1 + R2 * cos(V)) * (cos(U) * XDir + sin(U) * YDir) + R2 * sin(V) * ZDir;
/// U and V in [0, 2*PI].
/// </summary>
public sealed class ToroidalSurface : ElementarySurface
{
    private double _majorRadius;
    private double _minorRadius;

    /// <summary>A torus of radii MajorRadius and MinorRadius whose local coordinate system is A3.</summary>
    /// <exception cref="ConstructionErrorException">MinorRadius &lt; 0 or MajorRadius &lt; 0.</exception>
    public ToroidalSurface(in CoordinateSystem a3, double majorRadius, double minorRadius)
    {
        _majorRadius = majorRadius;
        _minorRadius = minorRadius;
        if (minorRadius < 0.0 || majorRadius < 0.0)
        {
            throw Refusal.Argument(new ConstructionErrorException());
        }
        else
        {
            _pos = a3;
        }
    }

    /// <summary>A torus from a gp torus.</summary>
    public ToroidalSurface(in Torus3D t)
    {
        _majorRadius = t.MajorRadius;
        _minorRadius = t.MinorRadius;
        _pos = t.Position;
    }

    public sealed override Geometry3D Copy()
    {
        ToroidalSurface cs;
        cs = new ToroidalSurface(_pos, _majorRadius, _minorRadius);
        return cs;
    }

    /// <summary>The major radius.</summary>
    public double MajorRadius => _majorRadius;

    /// <summary>The minor radius.</summary>
    public double MinorRadius => _minorRadius;

    /// <summary>2*PI - U.</summary>
    public sealed override double UReversedParameter(double u) => (2.0 * M_PI - u);

    /// <summary>2*PI - V.</summary>
    public sealed override double VReversedParameter(double v) => (2.0 * M_PI - v);

    /// <summary>True.</summary>
    public sealed override bool IsUClosed => true;

    /// <summary>True.</summary>
    public sealed override bool IsVClosed => true;

    /// <summary>True (period 2*PI).</summary>
    public sealed override bool IsUPeriodic => true;

    /// <summary>True (period 2*PI).</summary>
    public sealed override bool IsVPeriodic => true;

    /// <exception cref="ConstructionErrorException">MajorRadius - MinorRadius &lt;= Resolution.</exception>
    internal void SetMajorRadius(double majorRadius)
    {
        CheckMutable();
        if (majorRadius - _minorRadius <= Constants.Resolution())
        {
            throw Refusal.Argument(new ConstructionErrorException());
        }
        else
        {
            _majorRadius = majorRadius;
        }
    }

    /// <exception cref="ConstructionErrorException">MinorRadius &lt; 0 or MajorRadius - MinorRadius &lt;= Resolution.</exception>
    internal void SetMinorRadius(double minorRadius)
    {
        CheckMutable();
        if (minorRadius < 0.0 || _majorRadius - minorRadius <= Constants.Resolution())
        {
            throw Refusal.Argument(new ConstructionErrorException());
        }
        else
        {
            _minorRadius = minorRadius;
        }
    }

    internal void SetTorus(in Torus3D t)
    {
        CheckMutable();
        _minorRadius = t.MinorRadius;
        _majorRadius = t.MajorRadius;
        _pos = t.Position;
    }

    /// <summary>A copy of major radius MajorRadius.</summary>
    /// <exception cref="ConstructionErrorException">MajorRadius - MinorRadius &lt;= Resolution.</exception>
    public ToroidalSurface WithMajorRadius(double majorRadius)
    {
        ToroidalSurface copy = (ToroidalSurface)Copy();
        copy.SetMajorRadius(majorRadius);
        return copy;
    }

    /// <summary>A copy of minor radius MinorRadius.</summary>
    /// <exception cref="ConstructionErrorException">MinorRadius &lt; 0 or MajorRadius - MinorRadius &lt;= Resolution.</exception>
    public ToroidalSurface WithMinorRadius(double minorRadius)
    {
        ToroidalSurface copy = (ToroidalSurface)Copy();
        copy.SetMinorRadius(minorRadius);
        return copy;
    }

    /// <summary>A copy that is the torus T.</summary>
    public ToroidalSurface WithTorus(in Torus3D t)
    {
        ToroidalSurface copy = (ToroidalSurface)Copy();
        copy.SetTorus(t);
        return copy;
    }

    /// <summary>The area, 4 * PI**2 * R1 * R2.</summary>
    public double Area => 4.0 * M_PI * M_PI * _minorRadius * _majorRadius;

    /// <summary>U and V in [0, 2*PI].</summary>
    internal sealed override void ParameterBounds(out double u1, out double u2, out double v1, out double v2)
    {
        u1 = 0.0;
        v1 = 0.0;
        u2 = 2 * M_PI;
        v2 = 2 * M_PI;
    }

    /// <summary>
    /// The 35 coefficients of the implicit quartic equation, in Coef from its lower bound (see gp_Torus).
    /// </summary>
    /// <exception cref="DimensionErrorException">Coef has fewer than 35 elements.</exception>
    internal void Coefficients(NCollection_Array1<double> coef)
    {
        Torus3D tor = new Torus3D(_pos, _majorRadius, _minorRadius);
        tor.Coefficients(coef.AsSpan());
    }

    internal sealed override Point3D EvalD0(double u, double v)
    {
        Point3D p;
        global::Kerf.Engine.Geometry.ElSLib.TorusD0(u, v, _pos, _majorRadius, _minorRadius, out p);
        return p;
    }

    internal sealed override ResD1 EvalD1(double u, double v)
    {
        ResD1 result;
        global::Kerf.Engine.Geometry.ElSLib.TorusD1(u, v, _pos, _majorRadius, _minorRadius, out result.Point, out result.D1U, out result.D1V);
        return result;
    }

    internal sealed override ResD2 EvalD2(double u, double v)
    {
        ResD2 result;
        global::Kerf.Engine.Geometry.ElSLib.TorusD2(u,
                       v,
                       _pos,
                       _majorRadius,
                       _minorRadius,
                       out result.Point,
                       out result.D1U,
                       out result.D1V,
                       out result.D2U,
                       out result.D2V,
                       out result.D2UV);
        return result;
    }

    internal sealed override ResD3 EvalD3(double u, double v)
    {
        ResD3 result;
        global::Kerf.Engine.Geometry.ElSLib.TorusD3(u,
                       v,
                       _pos,
                       _majorRadius,
                       _minorRadius,
                       out result.Point,
                       out result.D1U,
                       out result.D1V,
                       out result.D2U,
                       out result.D2V,
                       out result.D2UV,
                       out result.D3U,
                       out result.D3V,
                       out result.D3UUV,
                       out result.D3UVV);
        return result;
    }

    /// <exception cref="UndefinedDerivative3DException">Nu + Nv &lt; 1, Nu &lt; 0 or Nv &lt; 0.</exception>
    internal sealed override Vector3D EvalDN(double u, double v, int nu, int nv)
    {
        if (nu + nv < 1 || nu < 0 || nv < 0)
        {
            throw Refusal.State(new UndefinedDerivative3DException());
        }
        return global::Kerf.Engine.Geometry.ElSLib.TorusDN(u, v, _pos, _majorRadius, _minorRadius, nu, nv);
    }

    /// <summary>The non-persistent gp torus with the same geometry.</summary>
    public Torus3D Torus => new Torus3D(_pos, _majorRadius, _minorRadius);

    /// <summary>The U iso-parametric circle (a Geom_Circle).</summary>
    public sealed override Curve3D UIso(double u)
    {
        CircleCurve3D gc = new CircleCurve3D(global::Kerf.Engine.Geometry.ElSLib.TorusUIso(_pos, _majorRadius, _minorRadius, u));
        return gc;
    }

    /// <summary>The V iso-parametric circle (a Geom_Circle).</summary>
    public sealed override Curve3D VIso(double v)
    {
        CircleCurve3D gc = new CircleCurve3D(global::Kerf.Engine.Geometry.ElSLib.TorusVIso(_pos, _majorRadius, _minorRadius, v));
        return gc;
    }

    /// <summary>The volume, PI * R2**2 * 2 * PI * R1.</summary>
    public double Volume => (M_PI * _minorRadius * _minorRadius) * (2.0 * M_PI * _majorRadius);

    protected internal sealed override void Transform(in Transform3D t)
    {
        CheckMutable();
        _majorRadius = _majorRadius * Math.Abs(t.ScaleFactor);
        _minorRadius = _minorRadius * Math.Abs(t.ScaleFactor);
        _pos = _pos.Transformed(t);
    }
}
